// Everything the admin sees about ONE agent's stock, sales and settlement.
//
// Two ways an agent ends up with vouchers to sell, and they're handled
// differently on purpose:
//   * GENERATED by the agent themselves — paid for up front from their wallet
//     ("prepaid"), so they owe nothing on these.
//   * GIVEN by you (a batch pushed to that agent alone) — handed over on
//     trust, so what they sell from it is money they owe you until you record
//     it as collected. This is the settlement ledger.
//
// A batch pushed to several agents at once can't say who sold what, so it is
// left out of the ledger and reported separately rather than guessed at.
//
// All plain logic (no React, no storage) so every number can be tested.

import { sym } from "@/components/dashboard/shared/currency";
import type { RouterInfo } from "../data/dashboard-data";
import type { Voucher, VoucherBatch } from "../shared/types";

export type CollectionMethod = "Cash" | "Mobile Money" | "Bank Transfer" | "Other";

export const COLLECTION_METHODS: CollectionMethod[] = ["Cash", "Mobile Money", "Bank Transfer", "Other"];

// Money you collected FROM an agent for vouchers they sold from stock you gave them.
export type AgentCollection = {
  id: string;
  agentId: string;
  amount: number;
  method: CollectionMethod;
  reference: string;
  note: string;
  // When the money was actually handed over (the admin can back-date it).
  collectedOnMs: number;
  recordedBy: string;
};

// A sale is dated by when the voucher was used; older vouchers that never
// recorded that fall back to when they were generated.
export function saleTimeMs(voucher: Voucher) {
  return voucher.usedAtMs ?? voucher.generatedAtMs;
}

function round2(value: number) {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

export function priceOf(priceByPackage: Record<string, number>, packageName: string) {
  return priceByPackage[packageName] ?? 0;
}

export type AgentStock = {
  generated: Voucher[];
  given: Voucher[];
  // Vouchers in batches shared with other agents — not counted anywhere below.
  sharedCount: number;
  // Everything the agent can sell: generated + given.
  held: Voucher[];
};

export function agentStock(agentId: string, vouchers: Voucher[], batches: VoucherBatch[]): AgentStock {
  const batchById = new Map(batches.map((batch) => [batch.id, batch]));
  const generated = vouchers.filter((voucher) => voucher.agentId === agentId);
  const given: Voucher[] = [];
  let sharedCount = 0;

  vouchers.forEach((voucher) => {
    if (voucher.agentId === agentId || !voucher.batchId) return;
    const batch = batchById.get(voucher.batchId);
    if (!batch || !batch.assignedAgentIds.includes(agentId)) return;
    if (batch.assignedAgentIds.length === 1) given.push(voucher);
    else sharedCount += 1;
  });

  return { generated, given, sharedCount, held: [...generated, ...given] };
}

function startOfDay(date: Date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime();
}
function startOfWeek(date: Date) {
  const mondayOffset = date.getDay() === 0 ? 6 : date.getDay() - 1;
  return new Date(date.getFullYear(), date.getMonth(), date.getDate() - mondayOffset).getTime();
}
function startOfMonth(date: Date) {
  return new Date(date.getFullYear(), date.getMonth(), 1).getTime();
}

export type AgentStats = {
  totalGiven: number;
  totalSold: number;
  remaining: number;
  expired: number;
  sellThroughPercent: number;
  retailSalesValue: number;
  prepaidPayments: number;
  soldToday: { count: number; value: number };
  soldThisWeek: { count: number; value: number };
  soldThisMonth: { count: number; value: number };
};

export function agentStats(
  stock: AgentStock,
  batches: VoucherBatch[],
  agentId: string,
  priceByPackage: Record<string, number>,
  now: Date = new Date(),
): AgentStats {
  const sold = stock.held.filter((voucher) => voucher.status === "Used");
  const value = (list: Voucher[]) => round2(list.reduce((sum, v) => sum + priceOf(priceByPackage, v.packageName), 0));
  const since = (from: number) => {
    const list = sold.filter((voucher) => saleTimeMs(voucher) >= from && saleTimeMs(voucher) <= now.getTime());
    return { count: list.length, value: value(list) };
  };

  return {
    totalGiven: stock.held.length,
    totalSold: sold.length,
    remaining: stock.held.filter((voucher) => voucher.status === "Available").length,
    expired: stock.held.filter((voucher) => voucher.status === "Expired").length,
    sellThroughPercent: stock.held.length > 0 ? Math.round((sold.length / stock.held.length) * 1000) / 10 : 0,
    retailSalesValue: value(sold),
    // What the agent paid from their wallet when generating vouchers.
    prepaidPayments: round2(
      batches.filter((batch) => batch.agentId === agentId).reduce((sum, batch) => sum + (batch.walletCharged ?? 0), 0),
    ),
    soldToday: since(startOfDay(now)),
    soldThisWeek: since(startOfWeek(now)),
    soldThisMonth: since(startOfMonth(now)),
  };
}

// --- The settlement ledger ---------------------------------------------------

export type AgentLedger = {
  // Sold from stock YOU gave them, at full price (before any commission).
  owedGross: number;
  totalCollected: number;
  collectionsCount: number;
  collectedThisMonth: number;
  collectionsThisMonthCount: number;
  // Owed minus collected. Negative = they've paid more than they owe.
  balance: number;
  // Sold vouchers not yet covered by what's been collected, oldest first.
  unsettledVouchers: number;
  consignedSold: number;
};

export function agentLedger(
  stock: AgentStock,
  collections: AgentCollection[],
  priceByPackage: Record<string, number>,
  now: Date = new Date(),
): AgentLedger {
  const consignedSold = stock.given
    .filter((voucher) => voucher.status === "Used")
    .sort((a, b) => saleTimeMs(a) - saleTimeMs(b));
  const owedGross = round2(consignedSold.reduce((sum, v) => sum + priceOf(priceByPackage, v.packageName), 0));
  const totalCollected = round2(collections.reduce((sum, collection) => sum + collection.amount, 0));

  const monthStart = startOfMonth(now);
  const thisMonth = collections.filter((collection) => collection.collectedOnMs >= monthStart);

  // Collections settle the oldest sales first; once one sale can't be fully
  // covered, it and everything after it is still unsettled.
  let credit = totalCollected;
  let unsettled = 0;
  let stillCovering = true;
  consignedSold.forEach((voucher) => {
    const price = priceOf(priceByPackage, voucher.packageName);
    if (stillCovering && credit + 0.0001 >= price) {
      credit -= price;
    } else {
      stillCovering = false;
      unsettled += 1;
    }
  });

  return {
    owedGross,
    totalCollected,
    collectionsCount: collections.length,
    collectedThisMonth: round2(thisMonth.reduce((sum, collection) => sum + collection.amount, 0)),
    collectionsThisMonthCount: thisMonth.length,
    balance: round2(owedGross - totalCollected),
    unsettledVouchers: unsettled,
    consignedSold: consignedSold.length,
  };
}

// --- Breakdowns -------------------------------------------------------------------

export type PackageRow = {
  packageName: string;
  batches: string[];
  given: number;
  sold: number;
  remaining: number;
  retailValue: number;
};

export function breakdownByPackage(
  stock: AgentStock,
  batches: VoucherBatch[],
  priceByPackage: Record<string, number>,
): PackageRow[] {
  const refOf = new Map(batches.map((batch) => [batch.id, batch.reference]));
  const rows = new Map<string, PackageRow>();
  stock.held.forEach((voucher) => {
    const row = rows.get(voucher.packageName) ?? {
      packageName: voucher.packageName,
      batches: [],
      given: 0,
      sold: 0,
      remaining: 0,
      retailValue: 0,
    };
    row.given += 1;
    if (voucher.status === "Used") {
      row.sold += 1;
      row.retailValue = round2(row.retailValue + priceOf(priceByPackage, voucher.packageName));
    }
    if (voucher.status === "Available") row.remaining += 1;
    const ref = voucher.batchId ? refOf.get(voucher.batchId) : undefined;
    if (ref && !row.batches.includes(ref)) row.batches.push(ref);
    rows.set(voucher.packageName, row);
  });
  return [...rows.values()].sort((a, b) => b.retailValue - a.retailValue || b.given - a.given);
}

export type BatchRow = {
  key: string;
  reference: string;
  given: number;
  delivery: string;
  sold: number;
  remaining: number;
  retailValue: number;
};

export function breakdownByBatch(
  stock: AgentStock,
  batches: VoucherBatch[],
  priceByPackage: Record<string, number>,
): BatchRow[] {
  const refOf = new Map(batches.map((batch) => [batch.id, batch.reference]));
  const groups = new Map<string, Voucher[]>();
  stock.held.forEach((voucher) => {
    const key = voucher.batchId && refOf.has(voucher.batchId) ? voucher.batchId : "__none__";
    groups.set(key, [...(groups.get(key) ?? []), voucher]);
  });
  return [...groups.entries()]
    .map(([key, list]) => {
      const deliveries = new Map<string, number>();
      list.forEach((v) => deliveries.set(v.delivery, (deliveries.get(v.delivery) ?? 0) + 1));
      const delivery = [...deliveries.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] ?? "—";
      return {
        key,
        reference: key === "__none__" ? "No batch" : (refOf.get(key) as string),
        given: list.length,
        delivery,
        sold: list.filter((v) => v.status === "Used").length,
        remaining: list.filter((v) => v.status === "Available").length,
        retailValue: round2(
          list.filter((v) => v.status === "Used").reduce((sum, v) => sum + priceOf(priceByPackage, v.packageName), 0),
        ),
      };
    })
    .sort((a, b) => b.given - a.given);
}

export type RouterRow = { ip: string; name: string; vouchersSold: number; latestSaleMs: number; retailValue: number };

// Sales per router, from the router(s) each voucher's batch covers — a sale
// in a batch covering two routers counts for both, like the revenue pages.
export function breakdownByRouter(
  stock: AgentStock,
  batches: VoucherBatch[],
  routers: RouterInfo[],
  priceByPackage: Record<string, number>,
): RouterRow[] {
  const routersOfBatch = new Map(batches.map((batch) => [batch.id, batch.routerIps]));
  const rows = new Map<string, RouterRow>();
  stock.held
    .filter((voucher) => voucher.status === "Used" && voucher.batchId)
    .forEach((voucher) => {
      (routersOfBatch.get(voucher.batchId as string) ?? []).forEach((ip) => {
        const router = routers.find((r) => r.ip === ip);
        if (!router) return;
        const row = rows.get(ip) ?? { ip, name: router.name.split(" (")[0], vouchersSold: 0, latestSaleMs: 0, retailValue: 0 };
        row.vouchersSold += 1;
        row.latestSaleMs = Math.max(row.latestSaleMs, saleTimeMs(voucher));
        row.retailValue = round2(row.retailValue + priceOf(priceByPackage, voucher.packageName));
        rows.set(ip, row);
      });
    });
  return [...rows.values()].sort((a, b) => b.retailValue - a.retailValue);
}

export function recentSales(stock: AgentStock, priceByPackage: Record<string, number>, limit = 10) {
  return stock.held
    .filter((voucher) => voucher.status === "Used")
    .sort((a, b) => saleTimeMs(b) - saleTimeMs(a))
    .slice(0, limit)
    .map((voucher) => ({
      code: voucher.code,
      packageName: voucher.packageName,
      usedAtMs: saleTimeMs(voucher),
      amount: priceOf(priceByPackage, voucher.packageName),
    }));
}

// Unsold vouchers the agent still holds — what "Reprint" works from.
export function unsoldVouchers(stock: AgentStock) {
  return stock.held.filter((voucher) => voucher.status === "Available");
}

export function timeAgo(ms: number, now: Date = new Date()): string {
  const seconds = Math.max(0, Math.round((now.getTime() - ms) / 1000));
  if (seconds < 60) return "just now";
  const units: Array<[string, number]> = [
    ["year", 31536000],
    ["month", 2592000],
    ["week", 604800],
    ["day", 86400],
    ["hour", 3600],
    ["minute", 60],
  ];
  for (const [name, size] of units) {
    if (seconds >= size) {
      const count = Math.floor(seconds / size);
      return `${count} ${name}${count === 1 ? "" : "s"} ago`;
    }
  }
  return "just now";
}

// --- Recording a collection ----------------------------------------------------------

export type CollectionDraft = { amount: string; method: CollectionMethod; collectedOn: string; reference: string; note: string };

export function validateCollection(draft: CollectionDraft, now: Date = new Date()): Partial<Record<"amount" | "collectedOn" | "reference" | "note", string>> {
  const errors: Partial<Record<"amount" | "collectedOn" | "reference" | "note", string>> = {};
  const amount = Number(draft.amount);
  if (draft.amount.trim() === "" || !Number.isFinite(amount) || amount <= 0) {
    errors.amount = "Enter the amount collected — more than 0.";
  } else if (amount > 1_000_000) {
    errors.amount = `That's more than ${sym()} 1,000,000 — check the amount.`;
  } else if (Math.round(amount * 100) / 100 !== amount) {
    errors.amount = "Use at most 2 decimal places.";
  }
  if (!draft.collectedOn) {
    errors.collectedOn = "Pick the date it was collected.";
  } else if (new Date(draft.collectedOn + "T00:00:00").getTime() > now.getTime()) {
    errors.collectedOn = "That date is in the future.";
  }
  if (draft.reference.length > 60) errors.reference = "Keep the reference under 60 characters.";
  if (draft.note.length > 300) errors.note = "Keep the note under 300 characters.";
  return errors;
}
